1: // Cart state and checkout totals for the Fieldwork Supply storefront.
2: const UNIT_PRICE_CENTS = 6400;
3: const SHIPPING_CENTS = 800;
4: const FREE_SHIPPING_THRESHOLD_CENTS = 10000;
5: let quantity = 0;
6: 
7: function calculateTotals(items) {
8:   const subtotal = items.reduce((sum, item) => sum + item.unitPriceCents, 0);
9:   const shipping =
10:     subtotal === 0 || subtotal >= FREE_SHIPPING_THRESHOLD_CENTS
11:       ? 0
12:       : SHIPPING_CENTS;
13:   return { subtotal, shipping, total: subtotal + shipping };
14: }
15: 
16: function money(cents) {
17:   return new Intl.NumberFormat("en-US", {
18:     style: "currency",
19:     currency: "USD",
20:   }).format(cents / 100);
21: }
22: 
23: function setMoney(testId, cents) {
24:   const element = document.querySelector(`[data-testid="${testId}"]`);
25:   element.textContent = money(cents);
26:   element.dataset.cents = String(cents);
27: }
28: 
29: function render() {
30:   document.querySelector("#empty").hidden = quantity > 0;
31:   document.querySelector("#cart-item").hidden = quantity === 0;
32:   document.querySelector("#quantity").value = quantity || 1;
33:   document.querySelector('[data-testid="bag-count"]').textContent = quantity;
34:   document.querySelector('[data-testid="item-count"]').textContent =
35:     `${quantity} ${quantity === 1 ? "item" : "items"}`;
36:   document.querySelector("#decrease").disabled = quantity <= 1;
37:   document.querySelector("#increase").disabled = quantity >= 9;
38:   const items = quantity
39:     ? [{ unitPriceCents: UNIT_PRICE_CENTS, quantity }]
40:     : [];
41:   const totals = calculateTotals(items);
42:   setMoney("line-total", quantity * UNIT_PRICE_CENTS);
43:   setMoney("subtotal", totals.subtotal);
44:   setMoney("shipping", totals.shipping);
45:   setMoney("total", totals.total);
46: }
47: 
48: document.querySelector("#add-to-cart").addEventListener("click", () => {
49:   quantity = Math.min(9, quantity + 1);
50:   render();
51: });
52: document.querySelector("#increase").addEventListener("click", () => {
53:   quantity = Math.min(9, quantity + 1);
54:   render();
55: });
56: document.querySelector("#decrease").addEventListener("click", () => {
57:   quantity = Math.max(1, quantity - 1);
58:   render();
59: });
60: document.querySelector("#quantity").addEventListener("change", (event) => {
61:   const value = Number.parseInt(event.target.value, 10);
62:   quantity = Number.isFinite(value) ? Math.max(1, Math.min(9, value)) : 1;
63:   render();
64: });
65: render();

